async function waitForHash(targetHash, tabWindow) {
  if (tabWindow.location.hash === targetHash) {
    return TestUtils.waitForTick();
  }
  return new Promise(resolve => {
    tabWindow.addEventListener("hashchange", () => {
      if (tabWindow.location.hash === targetHash) {
        resolve();
      }
    });
  });
}

